    @Nullable
    public static <T> T readOptional(CompoundNBT nbt, String key, Function<CompoundNBT, T> reader, T _default) {
        if (nbt.getBoolean(key + "_present")) {
            CompoundNBT read = nbt.getCompound(key);
            return reader.apply(read);
        }
        return _default;
    }

